"""Author PRE_A1-U12 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][11]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(11,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U12.UNDERSTAND';A='PRE_A1.U12.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('je','fr:je:first-person-subject','je','я (кто выполняет действие)','жё',ex('Je mange du pain.','Я ем хлеб.','жё ма(н)ж дю пэ́(н)'),1,[rev('je-meaning',fr('Je','жё'),['Он','Я','Она'],1,'Слово указывает на самого говорящего.','Здесь значение «я», а не другой человек.'),rev('je-use',ru('В образце нужно описать собственное действие от первого лица. Какое начало означает «я»?'),[fr('il','и́ль'),fr('elle','э́ль'),fr('je','жё')],2,'Выбрано начало сообщения о собственном действии.','Нужно слово «я»; два других варианта указывают не на самого говорящего.')])
addword('il','fr:il:masculine-subject','il','он (кто выполняет действие)','и́ль',ex('Il mange du pain.','Он ест хлеб.','иль ма(н)ж дю пэ́(н)'),1,[rev('il-meaning',fr('Il','и́ль'),['Он','Она','Я'],0,'Слово указывает на «он» в данном образце.','Нужно значение «он», а не «она» или «я».'),rev('il-use',ru('Нужно сообщить «Он пьёт воду». Выберите реплику с нужным действующим лицом.'),[fr('Elle boit de l’eau.','эль буа дё ло́'),fr('Il boit de l’eau.','иль буа дё ло́'),fr('Je bois de l’eau.','жё буа дё ло́')],1,'Реплика указывает, что действие выполняет он.','Нужно начало для «он»; действие у других лиц не соответствует условию.')])
addword('elle','fr:elle:feminine-subject','elle','она (кто выполняет действие)','э́ль',ex('Elle boit de l’eau.','Она пьёт воду.','эль буа дё ло́'),1,[rev('elle-meaning',fr('Elle','э́ль'),['Я','Он','Она'],2,'Слово указывает на «она» в данном образце.','Нужно значение «она», а не «он» или «я».'),rev('elle-use',ru('Нужно сообщить «Она ест хлеб». Выберите реплику с нужным действующим лицом.'),[fr('Elle mange du pain.','эль ма(н)ж дю пэ́(н)'),fr('Je mange du pain.','жё ма(н)ж дю пэ́(н)'),fr('Il mange du pain.','иль ма(н)ж дю пэ́(н)')],0,'Реплика сообщает действие от «она».','Нужно начало для «она»; остальные реплики относятся к другим лицам.')])
addword('manger','fr:manger:eat','manger','есть (принимать пищу)','ма(н)жэ́',ex('Je mange du pain.','Я ем хлеб.','жё ма(н)ж дю пэ́(н)'),1,[rev('manger-meaning',fr('Manger','ма(н)жэ́'),['Пить','Есть — принимать пищу','Хотеть'],1,'Слово называет действие приёма пищи.','Это действие «есть», а не пить или только хотеть.'),rev('manger-use',ru('По условию говорящий ест хлеб. Какую реплику выбрать?'),[fr('Je bois de l’eau.','жё буа дё ло́'),fr('Je veux du pain.','жё вё дю пэ́(н)'),fr('Je mange du pain.','жё ма(н)ж дю пэ́(н)')],2,'Реплика сообщает о приёме пищи.','Нужно действие «ем»; пить воду и хотеть хлеба — другие сообщения.')])
addword('boire','fr:boire:drink','boire','пить','буа́р',ex('Je bois de l’eau.','Я пью воду.','жё буа дё ло́'),1,[rev('boire-meaning',fr('Boire','буа́р'),['Пить','Есть','Хотеть'],0,'Слово называет действие питья.','Нужно значение «пить», а не есть или сообщать о желании.'),rev('boire-use',ru('В условии говорящий пьёт воду, а не просит её. Какую реплику выбрать?'),[fr('Je voudrais de l’eau.','жё вудрэ дё ло́'),fr('Je bois de l’eau.','жё буа дё ло́'),fr('Je mange du pain.','жё ма(н)ж дю пэ́(н)')],1,'Реплика сообщает само действие.','Нужно «пью», а не просьба получить воду или приём пищи.')])
addword('lire','fr:lire:read','lire','читать','ли́р',ex('Je lis un livre.','Я читаю книгу.','жё ли э(н) ли́вр'),2,[rev('lire-meaning',fr('Lire','ли́р'),['Писать','Пить','Читать'],2,'Слово называет чтение.','Правильное значение — читать; письмо и питьё обозначаются иначе.'),rev('lire-use',ru('По условию он читает книгу. Какую реплику выбрать?'),[fr('Il lit un livre.','иль ли э(н) ли́вр'),fr('Il boit de l’eau.','иль буа дё ло́'),fr('Il mange du pain.','иль ма(н)ж дю пэ́(н)')],0,'Реплика сообщает чтение книги.','Нужно чтение; два других варианта описывают питьё и еду.')])
addword('ecrire','fr:ecrire:write','écrire','писать','экри́р',ex('J’écris un mot.','Я пишу слово.','жэкри э(н) мо́'),2,[rev('ecrire-meaning',fr('Écrire','экри́р'),['Писать','Читать','Пить'],0,'Слово называет письмо.','Нужно значение «писать», а не чтение или питьё.'),rev('ecrire-use',ru('В условии говорящий пишет слово. Какую реплику выбрать?'),[fr('Je lis un livre.','жё ли э(н) ли́вр'),fr('J’écris un mot.','жэкри э(н) мо́'),fr('Je bois de l’eau.','жё буа дё ло́')],1,'Реплика сообщает действие письма.','Нужно «пишу слово»; чтение книги и питьё воды не подходят.')])
addword('mot','fr:mot:word','un mot','слово (в тексте)','э(н) мо́',ex('J’écris un mot.','Я пишу слово.','жэкри э(н) мо́'),2,[rev('mot-meaning',fr('Un mot','э(н) мо́'),['Книга','Слово в тексте','Вода'],1,'Это одно слово, а не целая книга.','Нужно значение «слово»; книга и вода означают другое.'),rev('mot-use',ru('По условию пишут одно слово. Какое сочетание называет именно этот элемент текста?'),[fr('Un livre','э(н) ли́вр'),fr('De l’eau','дё ло́'),fr('Un mot','э(н) мо́')],2,'Выбрано название одного слова.','Нужно слово; книга обозначает другой объект, вода не является элементом текста.')])
addword('aller','fr:aller:go','aller','идти, направляться (в образце движения)','алэ́',ex('Je vais à la table.','Я иду к столу.','жё вэ а ла та́бль'),3,[rev('aller-meaning',fr('Aller','алэ́'),['Ждать','Идти, направляться','Читать'],1,'В этом значении слово сообщает движение к месту.','Нужно значение движения; ожидание и чтение — другие действия.'),rev('aller-use',ru('В сценке она идёт к столу. Какую реплику выбрать?'),[fr('Elle lit un livre.','эль ли э(н) ли́вр'),fr('Je vais à la table.','жё вэ а ла та́бль'),fr('Elle va à la table.','эль ва а ла та́бль')],2,'Реплика сообщает её движение к столу.','Нужно действие от «она» и движение, а не чтение или сообщение от себя.')])
addword('attendre','fr:attendre:wait','attendre','ждать','ата́(н)др',ex('J’attends.','Я жду.','жата́(н)'),3,[rev('attendre-meaning',fr('Attendre','ата́(н)др'),['Ждать','Идти','Читать'],0,'Слово называет ожидание.','Правильный смысл — ждать; движение и чтение обозначаются иначе.'),rev('attendre-use',ru('Говорящий сообщает, что ждёт. Какую реплику выбрать?'),[fr('Je vais à la table.','жё вэ а ла та́бль'),fr('J’attends.','жата́(н)'),fr('Je lis un livre.','жё ли э(н) ли́вр')],1,'Реплика сообщает ожидание.','Нужно «Я жду», а не движение к столу или чтение книги.')])
addword('ecouter','fr:ecouter:listen','écouter','слушать','экутэ́',ex('J’écoute la radio.','Я слушаю радио.','жэкут ла радьо́'),4,[rev('ecouter-meaning',fr('Écouter','экутэ́'),['Смотреть','Ждать','Слушать'],2,'Слово называет действие слушать.','Нужно значение «слушать», а не смотреть или ждать.'),rev('ecouter-use',ru('По условию он слушает радио. Какую реплику выбрать?'),[fr('Il écoute la radio.','иль экут ла радьо́'),fr('Elle écoute la radio.','эль экут ла радьо́'),fr('Il attend.','иль ата́(н)')],0,'В реплике нужное лицо выполняет действие слушания.','Нужно «Он слушает радио»; другое лицо и ожидание не подходят.')])
addword('regarder','fr:regarder:look-watch','regarder','смотреть','рёгардэ́',ex('Je regarde la télé.','Я смотрю телевизор.','жё рёгард ла тэле́'),4,[rev('regarder-meaning',fr('Regarder','рёгардэ́'),['Слушать','Смотреть','Ждать'],1,'Слово называет действие смотреть.','Нужно значение «смотреть», а не слушать или ждать.'),rev('regarder-use',ru('Говорящий смотрит телевизор. Какую реплику выбрать?'),[fr('J’écoute la radio.','жэкут ла радьо́'),fr('J’attends.','жата́(н)'),fr('Je regarde la télé.','жё рёгард ла тэле́')],2,'Реплика сообщает просмотр телевизора.','Нужно действие смотреть; слушание радио и ожидание не подходят.')])
addword('radio','fr:radio:radio','la radio','радио','ла радьо́',ex('J’écoute la radio.','Я слушаю радио.','жэкут ла радьо́'),4,[rev('radio-meaning',fr('La radio','ла радьо́'),['Радио','Книга','Яблоко'],0,'Это название радио.','Правильный смысл — радио; книга и яблоко означают другое.'),rev('radio-use',ru('В учебной реплике слушают радио. Какое сочетание называет именно радио?'),[fr('Un livre','э(н) ли́вр'),fr('La radio','ла радьо́'),fr('Une pomme','юн по́м')],1,'Выбрано название радио.','Нужно радио; два других сочетания называют книгу и яблоко.')])
addword('tele','fr:tele:television','la télé','телевизор (в выражении «смотреть телевизор»)','ла тэле́',ex('Elle regarde la télé.','Она смотрит телевизор.','эль рёгард ла тэле́'),4,[rev('tele-meaning',fr('La télé','ла тэле́'),['Радио','Книга','Телевизор'],2,'В данном образце это телевизор.','Нужно значение из выражения «смотреть телевизор», а не радио или книга.'),rev('tele-use',ru('Нужно выбрать название из выражения «смотреть телевизор». Какое сочетание подходит?'),[fr('La télé','ла тэле́'),fr('La radio','ла радьо́'),fr('Un livre','э(н) ли́вр')],0,'Выбрано название из показанного выражения про телевизор.','Нужно сочетание с телевизором; радио и книга обозначают другие объекты.')])

s=start(1,'Понимайте сообщения о еде и питье и определяйте действующее лицо по словам фразы. Отличайте действие от желания получить продукт.',['je','il','elle','manger','boire','pain','eau','je-veux'])
choose(s,'reading',['PRE_A1.U11.UNDERSTAND'],['je-veux','pain'],['je-veux'],'Вспомните желание: что сообщает эта реплика?',fr('Je veux du pain.','жё вё дю пэ́(н).'),['Говорящий просит ещё хлеба','Говорящий прямо хочет хлеба','Говорящий завершает просьбу'],1,'Это прямое сообщение о желании получить хлеб.','Нужно значение «хочу»; добавка и завершение этой репликой не выражены.')
intro(s,2,'Je — «я». Два действия: manger — «есть, принимать пищу», boire — «пить». О себе используем готовые образцы Je mange du pain. — «Я ем хлеб» и Je bois de l’eau. — «Я пью воду». Формы действия запоминаем в этих фразах; полная таблица спряжения не нужна.',['je','manger','boire'],[('Je','жё'),('manger','ма(н)жэ́'),('boire','буа́р'),('Je mange du pain.','жё ма(н)ж дю пэ́(н)'),('Je bois de l’eau.','жё буа дё ло́')],('Je mange du pain. Je bois de l’eau.','жё ма(н)ж дю пэ́(н). жё буа дё ло́.'))
phrase_pairs(s,[U],[('Je mange du pain.','жё ма(н)ж дю пэ́(н)','Я ем хлеб.',['je','manger','pain'],['manger']),('Je bois de l’eau.','жё буа дё ло́','Я пью воду.',['je','boire','eau'],['boire']),('Je veux du pain.','жё вё дю пэ́(н)','Я хочу хлеба.',['je-veux','pain'],['je-veux'])],'Вы различили два действия и знакомое желание.','Есть, пить и хотеть получить продукт — разные сообщения; связывайте фразу с её прямым смыслом.')
listen(s,[U],['je','boire','eau','je-veux'],['je','boire'],'Кто выполняет действие и что сообщает фраза?','Je bois de l’eau.','жё буа дё ло́.',['Он пьёт воду','Я пью воду','Я хочу воды'],1,'Слово «я» относится к говорящему; действие — пить воду.','Нужно «Я пью воду». Другой человек и только желание получить воду не соответствуют фразе.')
intro(s,4,'Il — «он», elle — «она». В этих образцах с обоими началами используем mange для еды и boit для питья. Например, Il mange du pain. — «Он ест хлеб», Elle boit de l’eau. — «Она пьёт воду». Действующее лицо определяем по слову, а не по голосу браузера.',['il','elle'],[('Il','и́ль'),('elle','э́ль'),('mange','ма́(н)ж'),('boit','буа́'),('Il mange du pain.','иль ма(н)ж дю пэ́(н)'),('Elle boit de l’eau.','эль буа дё ло́')],('Il mange du pain. Elle boit de l’eau.','иль ма(н)ж дю пэ́(н). эль буа дё ло́.'))
